import math


def wrap(a):
    return math.atan2(math.sin(a), math.cos(a))


def compose(pose, delta):
    x, y, t = pose
    dx, dy, dt = delta
    return (x + dx * math.cos(t) - dy * math.sin(t),
            y + dx * math.sin(t) + dy * math.cos(t),
            wrap(t + dt))


track = (0.0, 0.0, 0.0)
print("step   x       y       theta")
for i in range(5):
    track = compose(track, (0.4, 0.0, 0.6))
    print(i + 1, "  ", round(track[0], 3), "  ", round(track[1], 3), "  ", round(track[2], 3))
print("heading stayed inside pi:", abs(track[2]) <= math.pi)

