    a = cloud - cloud.mean(axis=0)
    b = moved - moved.mean(axis=0)
    gap = np.linalg.norm(cloud.mean(axis=0) - moved.mean(axis=0))
    print(label, "centroid gap", round(float(gap), 4),
          " worst residual after centring", round(float(np.abs(a - b).max()), 6))
