    best, sc, _ = sweep(table[0], table[1], table[2], src, (0.0, 0.0, 0.0), 1.2, 0.8, 0.2, 0.1)
    return sweep(table[0], table[1], table[2], src, best, 0.3, 0.1, 0.02, 0.01)[2]


