    s = np.sqrt(np.diag(C))
    print(label, "sigma x", round(float(s[0]), 4), " sigma y", round(float(s[1]), 4),
          " sigma theta", round(float(s[2]), 4), " x over y", round(float(s[0] / s[1]), 1))
print("the corridor is uncertain along itself and sure across itself")

