    keys, travelled, turned = [0], 0.0, 0.0
    for i, (dx, dy, dt) in enumerate(odo):
        travelled += abs(dx)
        turned += abs(dt)
        # TODO: promote a keyframe when either budget is spent, then reset both
    return keys


odo = wheel_odometry()
print("scans", len(odo) + 1, "keyframes", len(keyframes(odo)))

