    wrong = sum(1 for s, t in scored if s >= th and not t)
    if wrong == 0 and taken > 0:
        safe = max(safe, th)
    print("  ", th, "          ", taken, "              ", wrong)
print("highest threshold with no false positives", safe,
      " keeping", sum(1 for s, t in scored if s >= safe and t), "of", real, "real closures")

