def runs(scan, jump=0.35, min_pts=6):
    out, cur = [], [0]
    for i in range(1, scan.shape[0]):
        if float(np.linalg.norm(scan[i] - scan[i - 1])) > jump:
            out.append(cur)
            cur = []
        cur.append(i)
    out.append(cur)
    return [np.array(r) for r in out if len(r) >= min_pts]


def deviation(pts, a, b):
    d = b - a
    L = float(np.linalg.norm(d))
    if L < 1e-9:
        return np.linalg.norm(pts - a, axis=1)
    n = np.array([-d[1], d[0]]) / L
    return np.abs((pts - a) @ n)


def split(pts, tol=0.05):
    if pts.shape[0] < 2:
        return []
    a, b = pts[0], pts[-1]
    dev = deviation(pts, a, b)
    k = int(np.argmax(dev))
    if dev[k] > tol and 0 < k < pts.shape[0] - 1:
        return split(pts[:k + 1], tol) + split(pts[k:], tol)
    return [(a, b)]


def merge(segs, ang_tol=0.15, gap_tol=0.12):
    out = []
    for a, b in segs:
        if out:
            pa, pb = out[-1]
            u = math.atan2(pb[1] - pa[1], pb[0] - pa[0])
            v = math.atan2(b[1] - a[1], b[0] - a[0])
            if abs(wrap(u - v)) < ang_tol and float(np.linalg.norm(a - pb)) < gap_tol:
                out[-1] = (pa, b)
                continue
        out.append((a, b))
    return out


def corners(segs, min_angle=0.6, max_gap=0.30):
    out = []
    for k in range(len(segs) - 1):
        a1, b1 = segs[k]
        a2, b2 = segs[k + 1]
        if float(np.linalg.norm(b1 - a2)) > max_gap:
            continue
        d1, d2 = b1 - a1, b2 - a2
        ang = abs(wrap(math.atan2(d1[1], d1[0]) - math.atan2(d2[1], d2[0])))
        ang = min(ang, math.pi - ang)
        if ang < min_angle:
            continue
        den = d1[0] * d2[1] - d1[1] * d2[0]
        if abs(den) < 1e-9:
            continue
        t = ((a2[0] - a1[0]) * d2[1] - (a2[1] - a1[1]) * d2[0]) / den
        out.append(a1 + t * d1)
    return out


def observe(pose, step, noise=FINE_NOISE, tol=0.05, min_len=0.4):
    scan = lidar(pose, step, noise=noise)
    found = []
    for r in runs(scan):
        segs = [(a, b) for a, b in split(scan[r], tol)
                if float(np.linalg.norm(b - a)) >= min_len]
        found += corners(merge(segs))
    return [xform(np.array([c]), pose)[0] for c in found]


def drifting_trail():
    truth = true_path()
    odo = wheel_odometry()
    scans = [lidar(t, i) for i, t in enumerate(truth)]
    nrms = [normals(s) for s in scans]
    est = [truth[0]]
    for i in range(1, len(truth)):
        g, res, inl = match(scans[i], scans[i - 1], nrms[i - 1], odo[i - 1])
        est.append(compose(est[-1], g))
    return est


def build_map(gate, poses):
    landmarks = []
    for step in range(0, 225, 5):
        for p in observe(poses[step], step):
            best, bd = -1, gate
            for k, (q, n) in enumerate(landmarks):
                d = float(np.linalg.norm(q - p))
                if d < bd:
                    bd, best = d, k
            if best >= 0:
                q, n = landmarks[best]
                landmarks[best] = ((q * n + p) / (n + 1), n + 1)
            else:
                landmarks.append((p, 1))
    return landmarks


truth = true_path()
trail = drifting_trail()
print("the trail this map is built on ends",
      round(math.hypot(trail[-1][0] - truth[-1][0], trail[-1][1] - truth[-1][1]), 3),
      "m from the truth")
